window.FIRMWARE_NOTES = {"YA4000S_FREKANS_YATOLYE.HEX": {"ad": "yATOLYE özel firmware'i", "ozet": "Orijinal YA4000S (AS V2-30) üzerine FREKANS (VFO) menüsü, APRS gönderme / alma, seçmeli çağrı kaldırıldı, açılışta 5 s yATOLYE.", "ozellikler": [{"baslik": "FREKANS (VFO) menüsü", "surum": "0-1", "aciklama": "Kanal tablosundan bağımsız alma ve gönderme frekansı, alma ve gönderme TKS (CTCSS) tonu tuşlarla girilir (tonlar V0-17 ile). Ekranda kanal numarası yerine VR (alma) / VT (gönderme); PTT'de gönderme frekansı görünür."}, {"baslik": "APRS gönderme", "surum": "0-1", "aciklama": "APRS menüsünde PTT ile ya da ayarlanan aralıkta (PTT'siz) 144,800 MHz'de 1200 baud konum paketi. Çağrı işareti, konum, simge, yorum ve aralık EEPROM'da (0x6E0); programlama sayfasının APRS sekmesinden düzenlenir."}, {"baslik": "APRS TR / DG / IG ayarları", "surum": "0-24", "aciklama": "Menüde APRS TR (tracker), APRS DG (digipeater), APRS IG (seri port / igate); 's' ile * / -. Yalnız TR açıkken normal kanalda arka plan tracker (30 s boşlukta 144,800). DG açıkken cihaz tipi APATAR. EEPROM 0x733."}, {"baslik": "GPS konumu", "surum": "0-26", "aciklama": "Seri porttan $GPRMC (GPS ya da sayfadaki benzetim); APRS ekranında dakikada bir konum güncellenir, paketlerde kullanılır; ekranda GPS."}, {"baslik": "APRS alma: duyulan istasyonlar", "surum": "0-6", "aciklama": "APRS menüsündeyken çözülen paketin gönderen çağrı işareti ~4 s ekranda. Son 8 istasyon listesi: * bir eskiye, # bir yeniye."}, {"baslik": "APRS alma: istasyon konumu ve mesajı", "surum": "0-22", "aciklama": "Listede bir istasyon görünürken 's': enlem, boylam, mesaj (ilk 8 karakter), çağrı işareti sayfaları (8 s). Düz konum biçimleri; sıkıştırılmış ve Mic-E konumu çözülmez (Mic-E yorumu gösterilir)."}, {"baslik": "APRS alma: seri port çıkışı", "surum": "0-18", "aciklama": "Çözülen her paket UART0'a (programlama kablosu, 9600 8N1) TNC2 satırı olarak yazılır. 160 baytı aşan paketlerin bilgi alanı kesilir."}, {"baslik": "APRS'te sessiz hoparlör", "surum": "0-7", "aciklama": "APRS menüsündeyken bip, uyarı ve hoparlör kapalı; alma çözücüsü çalışmaya devam eder."}, {"baslik": "APRS modunu hatırlama", "surum": "0-4", "aciklama": "Telsiz APRS menüsündeyken kapatılırsa açılışta yine APRS'te başlar (EEPROM 0x732)."}, {"baslik": "Tarama", "surum": "0-16", "aciklama": "Orijinal tarama (LIST menüsü + p tuşu) çalışır; TKS'li kanallarda ton için daha uzun bekleme (ASELSAN V2-51 / V2-54'ten)."}, {"baslik": "Sadeleştirilmiş firmware", "surum": "0-1", "aciklama": "Select-5 (CCIR / ZVEI / EEA) kodu ve '#' ile arama kaldırıldı; yer yeni özelliklere açıldı. Trunk, veri mesajı, ses yayın, yazıcı ve servis terminali de kapalı (V0-19 / V0-21). Yalnız Türkçe (V0-22). Parola, servis kodu ve RSSI göstergesi yok (V0-32)."}, {"baslik": "Açılış ekranı ve sürüm", "surum": "0-1", "aciklama": "Açılışta 5 s yATOLYE, ardından AT V0-x sürüm numarası. Sürüm, tarih ve metin ROM başlığında; T4000 ve yükleme sayfası da gösterir."}, {"baslik": "Güç ve monitör tuşları", "surum": "0-31", "aciklama": "p kısa: güç yüksek / düşük (YUKSEK G / ALCAK G); p uzun (~1 s): tarama; q: monitör (MONITOR* / MONITOR-)."}], "surumler": [{"surum": "0-32", "tarih": "2026-10-22", "durum": "sim", "degisiklik": ["ALT MENU'den PAROLA kaldırıldı. Telsizde daha önce parola konduysa açılışta sorulmaz ve silinir; parola yüzünden kilitli kalan telsiz bu sürümle açılır.", "Gizli servis kodu (PAROLA ekranından girilen 25970 / 10992 / 00000) ve onunla açılan MSR RSSI kalibrasyonu kaldırıldı. Kalibre edilmiş telsizde de sinyal gücü (-115dBm gibi) artık kanal adının yerine gösterilmez."]}, {"surum": "0-31", "tarih": "2026-10-22", "durum": "sim", "yeni": ["Daire (p) tuşu güç: kısa basış çıkış gücünü yüksek / düşük yapar, ekranda ~1,5 s YUKSEK G / ALCAK G. Normal ekranda, ayarlanmış FREKANS ekranında ve APRS ekranında çalışır.", "Tarama artık p tuşunu ~1 s basılı tutarak başlar / durur; tarama sürerken kısa p de durdurur.", "Üçgen (q) tuşu monitör: susturmayı devre dışı bırakır / devreye alır, ekranda MONITOR* / MONITOR-."], "duzeltme": ["Menülerde q tuşu artık sonraki tuşları yutmuyor."]}, {"surum": "0-29", "tarih": "2026-10-22", "durum": "sim", "degisiklik": ["Kendi APRS paketlerimizin yolu WIDE2-2 (önceden WIDE1-1,WIDE2-1)."]}, {"surum": "0-28", "tarih": "2026-10-22", "durum": "sim", "degisiklik": ["APRS frekansı telsizin bandına göre: VHF telsizde 144,800 MHz, UHF telsizde 432,500 MHz (APRS ekranı ve arka plan tracker). Bant EEPROM'daki bant tabanından (0x58C) anlaşılır."]}, {"surum": "0-27", "tarih": "2026-10-22", "durum": "sim", "yeni": ["Arka planda tracker: yalnız APRS TR açıkken (DG, IG kapalı) telsiz normal kanalında (ya da VFO frekansında) kalır, orayı dinler ve oradan konuşur. Beacon süresi dolunca kanal gözlenir; 30 s kesintisiz sinyal yoksa 144,800'e geçip tracker paketini gönderir (ekranda APRS TX) ve kanala döner."], "degisiklik": ["APRS ekranında beacon kanalda sinyal varken beklenir, ilk boşlukta gider.", "Digipeater açıkken kendi paketlerimizin cihaz tipi (hedef) APATAR, değilken APIZCI.", "APRS ekranındaki 'APRS PTT' yazısı 'APRS AKT' (aktif; ekran 8 karakter)."]}, {"surum": "0-26", "tarih": "2026-10-21", "durum": "sim", "yeni": ["GPS: seri porta (programlama kablosu, 9600) bağlı bir GPS ya da programlama sayfasındaki GPS benzetimi $GPRMC gönderirse, APRS ekranındayken dakikada bir yeni konum alınır ve paketlerde EEPROM konumu yerine kullanılır; ekranda \"GPS\". GPS konumu yokken her saniye denenir; geçerli cümle gelmezse en geç iki dakikada EEPROM konumuna dönülür.", "Programlama sayfası: seri izlemede harita ve GPS benzetimi (haritadan nokta, GÖNDER: saniyede bir $GPRMC + $GPGGA)."], "duzeltme": ["Tracker açık ve aralık ayarlıyken duyulan istasyonun ekranda kalma süresi ve digipeater'ın 30 s tekrar engeli / PTT zaman aşımı işlemiyordu (geçen süre sayacı sıfırlanıyordu)."], "degisiklik": ["APRS paket tamponu 160'tan 140 bayta indi (GPS'e yer): seri porta yazılan / detayı çıkarılan paketlerde bilgi alanının ilk ~124 baytı; tekrarlanan paket en çok 131 bayt."]}, {"surum": "0-25", "tarih": "2026-10-21", "durum": "sim", "yeni": ["APRS digipeater (APRS DG açıkken, APRS ekranında): WIDE1-1 → ÇAĞRIM*, WIDE2-2 → ÇAĞRIM*,WIDE2-1, WIDE2-1 → ÇAĞRIM,WIDE2*, doğrudan çağrımız → ÇAĞRIM*. Kendi paketimiz, bizden geçmiş paket, başka yollar (WIDE3-3 …) ve son 30 s'de tekrarlanan aynı paket tekrarlanmaz. IG açıksa paket önce duyulduğu haliyle seri porta yazılır."], "degisiklik": ["Kendi gönderimimiz (PTT / tracker) bekleyen digi paketini iptal eder; verici ~3 s'de açılmazsa digi paketi bırakılır."]}, {"surum": "0-24", "tarih": "2026-10-21", "durum": "sim", "yeni": ["Menüde APRS'ten sonra APRS TR (tracker: otomatik konum paketi), APRS DG (digipeater) ve APRS IG (igate: duyulan paketleri seri porta yaz) öğeleri. Başlıkta '*' açık, '-' kapalı; 's' ile değişir. Ayarlar EEPROM 0x733'te kalıcı; programlama sayfasının APRS sekmesinden de değişir. Özellikler APRS ekranında çalışır.", "Programlama sayfası: giden / gelen baytları gösteren seri izleme (HEX / ASCII) ve telsize bir şey göndermeden yalnız dinleme."], "degisiklik": ["APRS DG ayarı bu sürümde yalnız kaydedilir; digipeater bir sonraki sürümde.", "İstasyon detay kodu flash'ta 0x01E600'e taşındı (0x011000 bölgesi doldu)."]}, {"surum": "0-23", "tarih": "2026-10-21", "durum": "sim", "yeni": ["APRS istasyon detayına mesaj sayfası: konumdan sonra 's' ile paketin metni (konum yorumu, durum, mesaj ya da Mic-E yorumu), ilk 8 karakter, büyük harf. Metin yoksa \"MESAJ -\". 8 istasyon için saklanır; tekrar duyulan istasyonun metni yenisiyle değişir, metinsiz pakette eskisi kalır."], "degisiklik": ["Konum kayıtları RAM'de yeniden yerleştirildi (metinlere yer açmak için)."]}, {"surum": "0-22", "tarih": "2026-10-21", "durum": "sim", "degisiklik": ["Dil desteği kaldırıldı: menüler ve mesajlar her zaman Türkçe. EEPROM'daki dil ayarı (0x018 bit 7) yok sayılır."], "yeni": ["APRS istasyon detayı: listede (ya da yeni duyulan) bir istasyon görünürken 's' ile enlem \"4050 63N\" ve boylam \"3109 39E\" sayfaları. Düz konum biçimleri (!, =, /, @); sıkıştırılmış konum ve Mic-E için \"KONUM -\". Konum 8 istasyon için kapatılan özelliklerden boşalan RAM'de tutulur."], "duzeltme": ["APRS listesi: aynı istasyon farklı yollu bir paketle duyulunca listeye ikinci kez giriyordu (adresin son baytındaki yol bitleri)."]}, {"surum": "0-21", "tarih": "2026-10-21", "durum": "sim", "degisiklik": ["Kullanılmayan özellikler kapatıldı (kod çalışmaz, giriş noktaları kesildi): trunk / RADIO (TELSIZ) modu, veri mesajı ve sipariş baskısı ('*' tuşu, seri komut 80 / 82), kablosuz ses yayın, '#' ile seçmeli çağrı araması, seri servis terminali (0xF8, 2400 baud), '*' servis / test modu. Seri programlama protokolü aynı."]}, {"surum": "0-19", "tarih": "2026-10-21", "durum": "sim", "duzeltme": ["APRS menüsünde gönderirken seri porta \"4       ·01/01 00:02\" gibi bir satır çıkıyordu: B tipi kartta YAZICI açıkken firmware'in yazdığı çağrı günlüğü. Yazıcı açıkken seri port 9600 yerine 2400 baud'a da geçiyordu."], "degisiklik": ["YAZICI / PRINTER menüsü (yazıcı, tarih, saat) kaldırıldı; EEPROM'da açık kalmışsa da açılışta kapalı başlar. Seri port her zaman 9600 8N1. Seçmeli çağrı (ANI) olmadan kullanım alanı yoktu.", "APRS menüsündeyken firmware'in çağrı günlüğü ayrıca susturuldu: seri portta yalnız APRS satırları."]}, {"surum": "0-18", "tarih": "2026-10-21", "durum": "sim", "yeni": ["APRS menüsündeyken havadan çözülen her geçerli paket seri porta (RS232, 9600 8N1) TNC2 metni olarak yazılır: \"TA7W-7>APRS,WIDE1-1*:!4050.63N/03109.39E>...\" + satır sonu. Bilgisayarda bir terminal programı ya da APRS yazılımı ile izlenebilir."], "degisiklik": ["APRS paketi menüye girerken değil, her gönderimden hemen önce EEPROM'dan kurulur (tampon almada seri port için kullanılıyor); gönderimden önce kısa bir EEPROM okuması eklenir."]}, {"surum": "0-17", "tarih": "2026-10-21", "durum": "sim", "yeni": ["FREKANS (VFO) modunda TKS (CTCSS) tonu: gönderme frekansından sonra 3. adımda alma tonu, 4. adımda gönderme tonu girilir (885 = 88,5 Hz, 100 = 100,0 Hz; en yakın standart ton). Boş # tonu değiştirmez (gönderme tonunda: alma ile aynı), 0 # ton yok."], "degisiklik": ["FREKANS ayarı artık 4 adım: alma frekansı, gönderme frekansı, alma tonu, gönderme tonu. Tonsuz hızlı ayar: frekanslardan sonra iki kez # (156525 # 160650 # # #)."]}, {"surum": "0-16", "tarih": "2026-10-21", "durum": "sim", "duzeltme": ["Tarama: önceki bütün FREKANS sürümlerinde p ile tarama başlatılınca telsiz kendini yeniden başlatıyordu (FREKANS kancası taramanın atladığı adresi bozuyordu)."], "degisiklik": ["Taramada TKS (CTCSS) tonlu kanalda tonun çözülmesi için bekleme uzadı (67 Hz: 480 → 800 ms, 250 Hz: 128 → 448 ms); ton geç çözüldüğünde kanal atlanmaz. ASELSAN'ın sonraki sürümlerinden (V2-51 / V2-54) alındı."]}, {"surum": "0-15", "tarih": "2026-10-20", "durum": "gercek", "degisiklik": ["APRS alma, gerçek telsizde en iyi çalışan hâline (AT V0-7) döndürüldü: duyulan istasyonun çağrı işareti ekranda görünür. V0-11 … V0-14'teki denemeler geri alındı."]}, {"surum": "0-14", "tarih": "2026-10-20", "durum": "sim", "geri_alindi": true, "degisiklik": ["APRS alma: taşıyıcı koşulu kaldırıldı, teşhis ekranı eklendi. Gerçek telsizde çalışmadı."]}, {"surum": "0-12", "tarih": "2026-10-19", "durum": "sim", "geri_alindi": true, "degisiklik": ["APRS alma: kesme seli koruması, çözücü yalnız taşıyıcı varken. Gerçek telsizde hiçbir paket duyulmadı."]}, {"surum": "0-11", "tarih": "2026-10-19", "durum": "sim", "geri_alindi": true, "yeni": ["APRS alma: paketin tamamı ekranda kayan yazı. Gerçek telsizde ilk paketten sonra takıldı."]}, {"surum": "0-7", "tarih": "2026-10-19", "durum": "gercek", "yeni": ["APRS menüsündeyken hoparlör kapalı; paketler yine çözülür."]}, {"surum": "0-6", "tarih": "2026-10-19", "durum": "gercek", "yeni": ["APRS alma: duyulan istasyonların çağrı işaretleri ekranda (~4 s).", "Son duyulan 8 istasyonun listesi: * bir eskiye, # bir yeniye."]}, {"surum": "0-4", "tarih": "2026-10-19", "durum": "gercek", "yeni": ["Telsiz APRS modundayken kapanırsa açılışta yine APRS modunda başlar (EEPROM 0x732)."]}, {"surum": "0-3", "tarih": "2026-10-19", "durum": "gercek", "duzeltme": ["APRS gönderme: paket yerine boş taşıyıcı gidiyordu (FX806 modülatörü vericide susturuluyordu)."]}, {"surum": "0-2", "tarih": "2026-10-19", "durum": "gercek", "degisiklik": ["SAYI, HESAP ve OYUN örnek menüleri bu firmware'den çıkarıldı (yer açmak için; ayrı HEX'lerde duruyor)."]}, {"surum": "0-1", "tarih": "2026-10-19", "durum": "gercek", "yeni": ["İlk numaralı sürüm: açılışta 5 s yATOLYE, ardından AT V0-1.", "FREKANS menüsü: kanal tablosundan bağımsız alma / gönderme frekansı (VFO); ekranda VR / VT.", "APRS menüsü: PTT'de ya da ayarlanan aralıkta 144,800 MHz'de konum paketi; ayarlar EEPROM'da (0x6E0).", "Seçmeli çağrı (Select-5) kaldırıldı."]}]}};
